commit 6238e8ae91c083245ce2f583f48590fd19004536
Author: Tarundeep Singh <tarundeep.singh@ittiam.com>
Date:   Wed Aug 25 23:51:49 2021 +0530

    FPMT: Fix LR MT reallocations if luma is RESTORE_NONE

    Fixed reallocation of LR MT buffers, in case there is a restoration
    type for chroma and for luma it is none. The LR buffers are reallocated
    only when number of rows for LR is more than the allocated.

    Change-Id: I71609849f7d1ab0a7eef256a92e99486f638a38c

diff --git a/av1/common/thread_common.c b/av1/common/thread_common.c
index b5465f4eda..518a15ab1d 100644
--- a/av1/common/thread_common.c
+++ b/av1/common/thread_common.c
@@ -841,8 +841,8 @@ static void foreach_rest_unit_in_planes_mt(AV1LrStruct *lr_ctxt,
   int i;
   assert(MAX_MB_PLANE == 3);

-  if (!lr_sync->sync_range || num_rows_lr != lr_sync->rows ||
-      num_workers > lr_sync->num_workers || num_planes != lr_sync->num_planes) {
+  if (!lr_sync->sync_range || num_rows_lr > lr_sync->rows ||
+      num_workers > lr_sync->num_workers || num_planes > lr_sync->num_planes) {
     av1_loop_restoration_dealloc(lr_sync, num_workers);
     av1_loop_restoration_alloc(lr_sync, cm, num_workers, num_rows_lr,
                                num_planes, cm->width);
diff --git a/av1/encoder/ethread.c b/av1/encoder/ethread.c
index 45c041a9b9..a85e05b9d9 100644
--- a/av1/encoder/ethread.c
+++ b/av1/encoder/ethread.c
@@ -647,9 +647,9 @@ void av1_init_mt_sync(AV1_COMP *cpi, int is_first_pass) {
       rst_unit_size = (RESTORATION_UNITSIZE_MAX >> 1);
     int num_rows_lr = av1_lr_count_units_in_tile(rst_unit_size, cm->height);
     int num_lr_workers = av1_get_num_mod_workers_for_alloc(p_mt_info, MOD_LR);
-    if (!lr_sync->sync_range || num_rows_lr != lr_sync->rows ||
+    if (!lr_sync->sync_range || num_rows_lr > lr_sync->rows ||
         num_lr_workers > lr_sync->num_workers ||
-        MAX_MB_PLANE != lr_sync->num_planes) {
+        MAX_MB_PLANE > lr_sync->num_planes) {
       av1_loop_restoration_dealloc(lr_sync, num_lr_workers);
       av1_loop_restoration_alloc(lr_sync, cm, num_lr_workers, num_rows_lr,
                                  MAX_MB_PLANE, cm->width);
